    <div class="section-box">
      <h3>&#9632; The Bot Threat Landscape for Academic Publishers</h3>
      <div class="threat-stats">
        <div class="threat-stat-row">
          <div class="threat-pct">47%</div>
          <div class="threat-bar-wrap">
